-- =============================================================================
-- 2026-10-25 — Migration 021: bank soal wawancara (mensetsu) + jawaban kandidat
-- -----------------------------------------------------------------------------
-- MASALAH YANG DIKUNCI
--   Simulator wawancara lama (InterviewSimulatorModal) hanya chat bebas dengan
--   AI; tidak ada bank soal, tidak ada isian per pertanyaan, dan tidak ada
--   penilaian. Materi wawancara LPK sendiri (15 berkas di F:/mendsetsu/mensetsu)
--   tidak pernah masuk aplikasi — 4 di antaranya hasil pindai yang bahkan tidak
--   terbaca sebagai teks.
--
--   Bank 177 soal hasil ekstraksi + OCR itu sekarang disimpan di sini supaya:
--     1. siswa bisa MENGISI jawabannya sendiri per pertanyaan (latihan + hafalan),
--     2. AI bisa menerjemahkan jawaban Indonesia siswa ke Jepang + cara baca,
--     3. admin bisa memperbaiki soal tanpa deploy ulang.
--
-- DUA TABEL, DUA PERAN
--   wawancara_soal     — bank soal (dibaca semua, ditulis admin). 'tahap' +
--                        'urutan' menentukan alur wawancara; 'jawaban_*' adalah
--                        CONTOH jawaban (helper), bukan jawaban siswa.
--   wawancara_jawaban  — jawaban per kandidat per soal, kunci (wa, soal_kode).
--
-- SINKRON DENGAN CV (penting)
--   'kolom_cv' / 'kolom_cv_jp' menamai kolom di master_database_candidate.
--   Kalau terisi, jawaban siswa TIDAK disimpan sebagai salinan: 'arti' ditulis
--   ke kolom CV dan 'jp' ke kolom CV versi Jepang. Jadi mengubah Jiko PR di CV AI
--   langsung terlihat di sini, dan sebaliknya — satu sumber, bukan dua yang
--   disamakan belakangan.
--   'romaji' tidak punya kolom CV, jadi selalu disimpan di wawancara_jawaban.
--   8 soal dipetakan: promosi_diri, kelebihan, kekurangan, keahlian_khusus, tujuan_ke_jepang, harapan_tabungan, rencana_setelah_pulang, hobi_dan_keterampilan.
--
-- RLS
--   Enabled tanpa policy (fail-closed), sama seperti tabel lain sejak 012.
--   Semua akses lewat service role di runtime fungsi.
-- =============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.wawancara_soal (
  kode            text PRIMARY KEY,              -- 'ms-001' … stabil, dipakai jawaban
  tahap           text NOT NULL,                 -- 13 tahap alur mensetsu
  urutan          integer NOT NULL,              -- urutan di dalam tahap
  jp              text NOT NULL,
  romaji          text NOT NULL,
  arti            text NOT NULL,                 -- pertanyaan Bahasa Indonesia
  jawaban_jp      text,                          -- contoh jawaban (helper)
  jawaban_romaji  text,
  jawaban_arti    text,
  kolom_cv        text,                          -- null = jawaban berdiri sendiri
  kolom_cv_jp     text,
  aktif           boolean NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS wawancara_soal_tahap_urutan_idx
  ON public.wawancara_soal (tahap, urutan);

CREATE TABLE IF NOT EXISTS public.wawancara_jawaban (
  wa          text NOT NULL,
  soal_kode   text NOT NULL REFERENCES public.wawancara_soal (kode) ON DELETE CASCADE,
  jp          text,
  romaji      text,
  arti        text,
  sumber      text NOT NULL DEFAULT 'siswa',     -- 'siswa' | 'ai'
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (wa, soal_kode)
);

CREATE INDEX IF NOT EXISTS wawancara_jawaban_wa_idx
  ON public.wawancara_jawaban (wa);

ALTER TABLE public.wawancara_soal ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wawancara_jawaban ENABLE ROW LEVEL SECURITY;

