  ('ms-054', 'Bahasa Jepang & Kualifikasi', 7, 'カタカナ、ひらがな、かんじはよめますか。', 'katakana, hiragana, kanji wa yomemasu ka.', 'Apakah Anda bisa membaca Katakana, Hiragana, dan Kanji?',
   'はい、ひらがなとカタカナは読めます。漢字は現在も勉強中です。', 'hai, hiragana to katakana wa yomemasu. kanji wa genzai mo benkyou chuu desu.', 'Ya, saya bisa membaca Hiragana dan Katakana. Kanji masih sedang saya pelajari.', null, null),
  ('ms-055', 'Bahasa Jepang & Kualifikasi', 8, 'かんじはなんもじぐらいおぼえていますか。', 'kanji wa nanmoji gurai oboete imasu ka.', 'Kira-kira sudah menghafal berapa huruf Kanji?',
   'はい、いまはさんびゃくじぐらいおぼえています。まいにちすこしずつべんきょうしています。', 'hai, ima wa sanbyakuji gurai oboete imasu. mainichi sukoshizutsu benkyou shite imasu.', 'Ya, sekarang saya sudah menghafal sekitar 300 kanji. Saya belajar sedikit demi sedikit setiap hari.', null, null),
  ('ms-056', 'Bahasa Jepang & Kualifikasi', 9, '日本語についてどう思いますか？', 'nihongo ni tsuite dou omoimasu ka?', 'Bagaimana pendapat Anda tentang bahasa Jepang?',
   '文法や漢字は難しいですが、とてもおもしろい言語だと思います。', 'bunpou ya kanji wa muzukashii desu ga, totemo omoshiroi gengo da to omoimasu.', 'Tata bahasa dan kanji sulit, tapi saya pikir itu adalah bahasa yang sangat menarik.', null, null),
  ('ms-057', 'Bahasa Jepang & Kualifikasi', 10, '日本語の勉強はどうですか。', 'nihongo no benkyou wa dou desu ka?', 'Bagaimana menurut Anda tentang belajar bahasa Jepang?',
   '文法や漢字が難しいですが、毎日楽しく勉強しています。', 'bunpou ya kanji ga muzukashii desu ga, mainichi tanoshiku benkyou shite imasu.', 'Tata bahasa dan kanji sulit, tetapi saya menikmatinya dan belajar setiap hari.', null, null),
  ('ms-058', 'Bahasa Jepang & Kualifikasi', 11, '日本語で一番難しいのは何ですか？', 'nihongo de ichiban muzukashii no wa nandesuka?', 'Apa yang paling sulit dalam bahasa Jepang?',
   '漢字の読み方と書き方を覚えるのが一番難しいです。', 'kanji no yomikata to kakikata o oboeru no ga ichiban muzukashii desu.', 'Yang paling sulit adalah menghafal cara baca dan tulis kanji.', null, null),
  ('ms-059', 'Bahasa Jepang & Kualifikasi', 12, '毎日どうやって日本語を勉強していますか？', 'mainichi douyatte nihongo o benkyoushite imasuka?', 'Bagaimana cara Anda belajar bahasa Jepang setiap hari?',
   '毎日、日本語のアプリで単語を覚えたり、アニメを見たりしています。', 'mainichi, nihongo no apuri de tango o oboetari, anime o mitari shiteimasu.', 'Setiap hari, saya menghafal kosakata lewat aplikasi bahasa Jepang dan menonton anime.', null, null),
  ('ms-060', 'Bahasa Jepang & Kualifikasi', 13, 'どうやって日本語を勉強しましたか。', 'doyatte nihongo o benkyoshimashita ka?', 'Bagaimana cara Anda belajar bahasa Jepang?',
